const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');
const root = '/workspace/master';
const files = ['README.md', 'app/docs/architecture.md', 'app/docs/protocol.md', 'app/docs/ops.md', 'app/docs/contributing.md', 'app/docs/performance.md'];
const linkRe = /\]\(([^)]+)\)/g;
let bad = 0, total = 0;
for (const f of files) {
  const p = path.join(root, f);
  const txt = fs.readFileSync(p, 'utf8');
  let m;
  while ((m = linkRe.exec(txt))) {
    const target = m[1].trim();
    if (/^(https?:|mailto:|#)/.test(target)) continue;
    total++;
    const base = target.split('#')[0];
    const [filePart, hash] = target.split('#');
    const fp = path.resolve(path.dirname(p), filePart);
    if (!fs.existsSync(fp)) { console.log(`MISSING FILE: ${f} -> ${target}`); bad++; continue; }
    if (hash) {
      const doc = fs.readFileSync(fp, 'utf8');
      const slugs = doc.split('\n').filter(l => /^#{1,6}\s/.test(l))
        .map(l => l.replace(/^#{1,6}\s+/, '').toLowerCase().replace(/[()]/g, '').replace(/[^a-z0-9\s_-]/g, '').trim().replace(/\s+/g, '-'));
      if (!slugs.includes(hash)) { console.log(`MISSING ANCHOR: ${f} -> ${target}`); bad++; }
    }
  }
}
console.log(`checked ${total} internal links, ${bad} broken`);

